/*
 * Blindhuhn search UI.
 *
 * Injected into pages generated by Agda's HTML backend. Renders a small
 * modal for jumping to modules and definitions. The actual index and
 * matching (see `blindhuhn-search-worker.js`) live in a SharedWorker, so
 * they are only fetched/built once per browsing session rather than once
 * per page.
 */

var WORKER_URL = "blindhuhn-search-worker.js";
var DEBOUNCE_MS = 60;

// The search UI connects to a SharedWorker.  These workers live as long
// as their origin is referenced by any open tab.  To prevent connecting
// to a stale worker, the worker is keyed by a hash of the search index.
// If the hash changes because of a rebuild, a new worker is created.
function indexHash() {
  var meta = document.querySelector('meta[name="blindhuhn-index-hash"]');
  return (meta && meta.content) || "";
}

function el(tag, attrs, children) {
  var node = document.createElement(tag);
  if (attrs) {
    Object.keys(attrs).forEach(function (key) {
      node.setAttribute(key, attrs[key]);
    });
  }
  (children || []).forEach(function (child) {
    node.appendChild(child);
  });
  return node;
}

function shortenModule(module) {
  var parts = module.split(".");
  if (parts.length <= 3) {
    return module;
  }
  return parts[0].charAt(0) + ".…." + parts.slice(-2).join(".");
}

function renderResults(list, matches) {
  list.innerHTML = "";
  matches.forEach(function (m) {
    var link = el("a", {
      href: m.path,
      class: "bh-search-result-link Function",
    });
    link.textContent = m.name;

    var mod = el("span", {
      class: "bh-search-result-module Module",
      title: m.module,
    });
    mod.textContent = shortenModule(m.module);

    list.appendChild(el("li", { class: "bh-search-result" }, [link, mod]));
  });
}

function buildUI() {
  var input = el("input", {
    id: "bh-search-input",
    type: "text",
    placeholder: "Search modules and definitions…",
    autocomplete: "off",
    spellcheck: "false",
  });
  var list = el("ul", { id: "bh-search-results" });
  var modal = el(
    "div",
    { id: "bh-search-modal", role: "dialog", "aria-label": "Search" },
    [input, list],
  );
  // Agda.css defines classes scoped under `.Agda`.  Apply this class
  // to the search overlay here so that we can style the results with
  // `.Module` and `.Function`.
  var overlay = el(
    "div",
    { id: "bh-search-overlay", class: "Agda", hidden: "hidden" },
    [modal],
  );
  document.body.appendChild(overlay);

  var trigger = el("button", {
    id: "bh-search-trigger",
    type: "button",
    title: "Search (press /)",
  });
  trigger.textContent = "⌕";
  document.body.appendChild(trigger);

  // The worker (and its connection) is only opened on first use.
  var port = null;
  var nextRequestId = 0;
  var latestRequestId = -1;
  var debounceTimer = null;

  function getPort() {
    if (!port) {
      var worker = new SharedWorker(WORKER_URL, {
        type: "module",
        // Key the worker by a hash of the search index to prevent
        // us from connecting to a worker that serves a stale index.
        name: indexHash(),
      });
      port = worker.port;
      port.onmessage = function (ev) {
        // Ignore replies to queries that have since been superseded by
        // a newer one (e.g. a slow response to an earlier keystroke).
        if (ev.data.requestId !== latestRequestId) {
          return;
        }
        renderResults(list, ev.data.results);
      };
      port.start();
    }
    return port;
  }

  function runQuery(query) {
    var trimmed = query.trim();
    if (trimmed === "") {
      list.innerHTML = "";
      latestRequestId = -1;
      return;
    }
    var requestId = ++nextRequestId;
    latestRequestId = requestId;
    getPort().postMessage({ requestId: requestId, query: trimmed });
  }

  function scheduleQuery(query) {
    if (debounceTimer) {
      clearTimeout(debounceTimer);
    }
    debounceTimer = setTimeout(function () {
      runQuery(query);
    }, DEBOUNCE_MS);
  }

  function isOpen() {
    return !overlay.hasAttribute("hidden");
  }

  function open() {
    overlay.removeAttribute("hidden");
    runQuery(input.value);
    input.focus();
    input.select();
  }

  function close() {
    overlay.setAttribute("hidden", "hidden");
    trigger.focus();
  }

  trigger.addEventListener("click", function () {
    isOpen() ? close() : open();
  });

  overlay.addEventListener("click", function (ev) {
    if (ev.target === overlay) {
      close();
    }
  });

  // Close the search modal whenever a result is clicked.
  list.addEventListener("click", function (ev) {
    if (ev.target.closest("a")) {
      close();
    }
  });

  input.addEventListener("input", function () {
    scheduleQuery(input.value);
  });

  document.addEventListener("keydown", function (ev) {
    var active = document.activeElement;
    var typing =
      active && (active.tagName === "INPUT" || active.tagName === "TEXTAREA");
    var hasSearchKeyCombo =
      ev.key === "/" ||
      (ev.key.toLowerCase() === "k" && (ev.ctrlKey || ev.metaKey));

    if (isOpen() && ev.key === "Escape") {
      ev.preventDefault();
      close();
    } else if (!isOpen() && !typing && hasSearchKeyCombo) {
      ev.preventDefault();
      open();
    }
  });
}

buildUI();
